def addEdge(adj, u, v):
    adj[u].append(v)

def dfs(node, adj, arr, visited):
    visited[node] = True

    for i in range(0, len(adj[node])):
        if not visited[adj[node][i]]:
            dfs(adj[node][i], adj, arr, visited)

    arr[node] = max(arr[node], 1 + arr[adj[node][i]])
